import java.util.*;
interface SaverMode {double getSaverUnits(double units);}
abstract class Appliance {double hours;Appliance(double h){hours=h;}abstract double getPower();abstract String getType();double calculateUnits(boolean saver){double units=getPower()*hours/1000.0;if(saver&&this instanceof SaverMode)units=((SaverMode)this).getSaverUnits(units);return units;}boolean supportsSaver(){return this instanceof SaverMode;}}
class Fridge extends Appliance {Fridge(double h){super(h);}double getPower(){return 150.0;}String getType(){return "FRIDGE";}}
class AC extends Appliance implements SaverMode {AC(double h){super(h);}double getPower(){return 1500.0;}public double getSaverUnits(double u){return u*.75;}String getType(){return "AC";}}
class TV extends Appliance {TV(double h){super(h);}double getPower(){return 100.0;}String getType(){return "TV";}}
class Washer extends Appliance implements SaverMode {Washer(double h){super(h);}double getPower(){return 500.0;}public double getSaverUnits(double u){return u*.75;}String getType(){return "WASHER";}}
public class HomeApplianceEnergyReport {public static void main(String[] args){Scanner sc=new Scanner(System.in);int n=sc.nextInt();double totalCost=0;for(int i=0;i<n;i++){String type=sc.next();double hours=sc.nextDouble();String remainder=sc.nextLine().trim();boolean saver=remainder.equals("SAVER");Appliance a;switch(type){case "FRIDGE":a=new Fridge(hours);break;case "AC":a=new AC(hours);break;case "TV":a=new TV(hours);break;default:a=new Washer(hours);}if(saver&&!a.supportsSaver()){System.out.println(a.getType()+": saver mode not supported");continue;}double units=a.calculateUnits(saver),cost=units*8.0;System.out.printf("%s: Units=%.2f Cost=%.2f%n",a.getType(),units,cost);totalCost+=cost;}System.out.printf("Total Cost: %.2f%n",totalCost);sc.close();}}